mapper.select:
SELECT id, public_no, user_id, chain, from_address AS address, amount, created_at AS at,
  created_at <= NOW(3) - INTERVAL (#{lagMillis} * 1000) MICROSECOND AS ripe
FROM wallet_deposit WHERE id > #{afterId} ORDER BY id LIMIT #{limit}

SELECT user_id, MIN(credited_at) AS at FROM wallet_deposit
WHERE credited_at IS NOT NULL AND user_id IN #{u}
GROUP BY user_id
